layout(std140) uniform ubProj
{
    highp mat4 projectionMatrix;
}

layout(std140) uniform ubVSMaterial
    {
        #if defined( USE_UV0 )
            vec4 uv0OffsetScale;
            float uv0Rotate;
            float uv0UnusedA;
            float uv0UnusedB;
            float uv0UnusedC;
        #endif

        #if defined( USE_UV1 )
            vec4 uv1OffsetScale;
            float uv1Rotate;
            float uv1UnusedA;
            float uv1UnusedB;
            float uv1UnusedC;
        #endif
    }

layout(std140) uniform ubFSShadowMapEnvironment
    {
        float shadowDarkness;
        float constantShadowBias;
        float kernelRadius;

        #if defined( USE_STATIC_SHADOWMAP )
            float normalStaticShadowBias;
            highp mat4 staticShadowMatrix;
        #else
            float paddingData1;
        #endif

        #if defined( USE_DYNAMIC_SHADOWMAP )
            highp mat4 dynamicShadowMatrices[ DYNAMIC_SHADOWMAP_MATRIX_COUNT ];
            float normalDynamicShadowBias[ DYNAMIC_SHADOWMAP_MATRIX_COUNT ];
        #endif
    }

layout(std140) uniform ubFSMaterial
{
    vec3 emissive;
    float opacity;

    #if !defined( USE_MAP )
        vec3 diffuseColorRGB;
    #endif

    #if defined( USE_SPECULAR )
        vec4 specColorShini;

        #if defined( REFLECTION ) && !defined( USE_REFRACTIONRATIOMAP )
            float refractionRatio;
            float ubUnusedB;
            float ubUnusedC;
        #endif
    #endif

    #if defined( USE_NORMALMAP )
        vec2 normalScale;
        float ubUnusedD;
        float ubUnusedE;
    #endif

    #if defined( USE_BUMPMAP )
        float bumpScale;
        float ubUnusedF;
        float ubUnusedG;
        float ubUnusedH;
    #endif
}

layout(std140) uniform ubFSEnvironment
{
    vec3  ambientColor;
    float ambientIntensity;

    float directionalLightCount;
    float pointLightCount;
    float spotLightCount;
    float paddingData0;

    #if MAX_DIR_LIGHTS > 0
    	vec4 directionalLightColorIntensity[ MAX_DIR_LIGHTS ];
    	vec4 directionalLightDirectionShadowmapIndex[ MAX_DIR_LIGHTS ];
    #endif

    #if MAX_POINT_LIGHTS > 0
    	vec4 pointLightColorIntensity[ MAX_POINT_LIGHTS ];
    	vec4 pointLightPositionRadius[ MAX_POINT_LIGHTS ];
    	vec2 pointLightAttenuationOffsetSmIndices[ MAX_POINT_LIGHTS ];
    #endif

    #if MAX_SPOT_LIGHTS > 0
    	vec4 spotLightColorIntensity[ MAX_SPOT_LIGHTS ];
    	highp vec4 spotLightPositionRadius[ MAX_SPOT_LIGHTS ];
    	vec4 spotLightDirectionShadowmapIndex[ MAX_SPOT_LIGHTS ];
        vec3 spotLightScaleOffsetAttenuation[ MAX_SPOT_LIGHTS ];
    #endif

    vec4 ambientSphericalHarmonics[9];
}

